import { HttpInterceptorFn } from '@angular/common/http';

/**
 * Derives the tenant slug from the browser's hostname so the backend can
 * resolve the correct organization even though the admin portal calls the
 * API at an absolute cross-origin URL (http://localhost:8080), where the
 * backend would otherwise only ever see "localhost" as the Host header.
 *
 * Examples:
 *   "tenant1.localhost"       -> "tenant1"
 *   "acme.example.com"        -> "acme"
 *   "localhost" / "127.0.0.1" -> null (main platform / super admin)
 */
function currentTenantSlug(): string | null {
  const host = window.location.hostname;
  if (host === 'localhost' || host === '127.0.0.1') {
    return null;
  }
  const parts = host.split('.');
  return parts.length > 1 ? parts[0] : null;
}

/**
 * Attaches the JWT access token from localStorage, plus the current tenant
 * slug (derived from the subdomain), to every outgoing HTTP request so the
 * backend can authenticate admin requests and scope them to the right
 * organization — including the login/register calls themselves.
 */
export const authInterceptor: HttpInterceptorFn = (req, next) => {
  const token = localStorage.getItem('access_token');
  const tenantSlug = currentTenantSlug();

  let headers = req.headers;
  if (token) {
    headers = headers.set('Authorization', `Bearer ${token}`);
  }
  if (tenantSlug) {
    headers = headers.set('X-Tenant-Slug', tenantSlug);
  }

  return next(req.clone({ headers }));
};
